#!/bin/sh
#
# Regenerates ../ps3shaders.h from the Cg sources in this folder.
# NOT part of the normal build: the header is in the tree, so building the
# game needs neither of these tools.
#
#   cgc     NVIDIA Cg Toolkit 3.1 (Ubuntu/WSL: sudo apt install nvidia-cg-toolkit)
#   cgcomp  PSL1GHT's, assembler mode only (-a): $PS3DEV/bin/cgcomp
#
# rw_skin needs relative constant addressing (c[A0.x + 32]), which stock
# cgcomp gets wrong (the read isn't indexed and the offset is lost): build
# cgcomp with cgcomp-relative-constants.patch and point CGCOMP at it.
#
# cgc turns Cg into NV40 assembly (vp40 / fp40), cgcomp -a turns that into
# the .vpo / .fpo binaries PSL1GHT loads (same two steps as Quake2PS3).
#
#   cd vendor/librw/src/ps3/shaders && sh build_shaders.sh

set -e

CGC=${CGC:-cgc}
CGCOMP=${CGCOMP:-$PS3DEV/bin/cgcomp}

command -v "$CGC" >/dev/null 2>&1 || { echo "cgc not found (sudo apt install nvidia-cg-toolkit)"; exit 1; }
[ -x "$CGCOMP" ] || { echo "cgcomp not found at $CGCOMP"; exit 1; }

TMP=$(mktemp -d)
trap 'rm -rf "$TMP"' EXIT

VPS="rw_default rw_skin rw_env rw_im2d rw_im3d"
FPS="rw_simple rw_env rw_add rw_addalpha"

for p in $VPS; do
	"$CGC" -quiet -profile vp40 -o "$TMP/$p.vpa" $p.vcg
	"$CGCOMP" -a -v "$TMP/$p.vpa" "$TMP/$p.vpo" >/dev/null
done
for p in $FPS; do
	"$CGC" -quiet -profile fp40 -o "$TMP/$p.fpa" $p.fcg
	"$CGCOMP" -a -f "$TMP/$p.fpa" "$TMP/$p.fpo" >/dev/null
done

python3 - "$TMP" "$VPS" "$FPS" <<'PYEOF'
import sys
tmp, vps, fps = sys.argv[1], sys.argv[2].split(), sys.argv[3].split()
out = ["/* ps3shaders.h -- GENERATED by shaders/build_shaders.sh, don't edit.",
       " * RSX programs (cgc vp40/fp40 + PSL1GHT cgcomp -a) of the Cg sources",
       " * in shaders/. */",
       "",
       "#ifndef PS3SHADERS_H",
       "#define PS3SHADERS_H",
       ""]
progs = [(p + ".vpo", p + "_vpo") for p in vps] + [(p + ".fpo", p + "_fpo") for p in fps]
for f, name in progs:
    data = open(tmp + "/" + f, "rb").read()
    out.append("static const unsigned char %s[] __attribute__((aligned(16))) = {" % name)
    for i in range(0, len(data), 12):
        out.append("\t" + ", ".join("0x%02x" % b for b in data[i:i+12]) + ",")
    out.append("};")
    out.append("")
out.append("#endif")
open("../ps3shaders.h", "w").write("\n".join(out) + "\n")
print("wrote ../ps3shaders.h (%d programs)" % len(progs))
PYEOF
